contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params:
    // depositAmt: amount of wei to send with Deposit
    function run(uint depositAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmt);

        // snapshot before-values
        uint beforeStored = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeCbal = address(c).balance;

        // attempt Deposit and record whether it reverted
        bool reverted;
        c.Deposit{value: depositAmt}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterStored = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterCbal = address(c).balance;

        // General rule: If Deposit did not revert, then the stored balance for this caller
        // did not decrease and the contract's Ether balance did not decrease.
        assert(reverted || (afterStored >= beforeStored && afterCbal >= beforeCbal));
    }

    receive() external payable { }
}

