// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 depositAmt) internal {
        depositAmt = bound(depositAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmt);
        uint256 beforeStored;
        try c.balances(address(this)) returns (uint256 __r) { beforeStored = __r; } catch { return; }
        uint beforeCbal = address(c).balance;
        bool reverted;
        try c.Deposit{value: depositAmt}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterStored;
        try c.balances(address(this)) returns (uint256 __r) { afterStored = __r; } catch { return; }
        uint afterCbal = address(c).balance;
        assertTrue(reverted || (afterStored >= beforeStored && afterCbal >= beforeCbal));
    }

    function testFuzz_run(uint256 depositAmt) public {
        _run(depositAmt);
    }

    receive() external payable { }
}
